labs.solution:
def conv_geometry(input_hw, kernel_hw, stride_hw=(1, 1), padding_hw=(0, 0), dilation_hw=(1, 1)):
    items = [input_hw, kernel_hw, stride_hw, padding_hw, dilation_hw]
    if any(len(values) != 2 for values in items):
        raise ValueError("几何参数必须为二维")
    output = []
    for length, kernel, stride, padding, dilation in zip(*items):
        if any(type(v) is not int or v <= 0 for v in (length, kernel, stride, dilation)):
            raise ValueError("长度、核、步长和 dilation 必须为正整数")
        if type(padding) is not int or padding < 0:
            raise ValueError("padding 必须为非负整数")
        size = (length + 2 * padding - dilation * (kernel - 1) - 1) // stride + 1
        if size <= 0:
            raise ValueError("没有有效输出位置")
        output.append(size)
    return tuple(output)

def receptive_field(layers):
    receptive, jump = 1, 1
    for kernel, stride, dilation in layers:
        if any(type(v) is not int or v <= 0 for v in (kernel, stride, dilation)):
            raise ValueError("核、步长和 dilation 必须为正整数")
        receptive += (kernel - 1) * dilation * jump
        jump *= stride
    return receptive, jump
